-- 3) 매출 — 이관분은 전표번호 접두어, 신규분(I-)은 **그 상품**을 따라간다.
--    ‼️거래처가 아니라 상품을 따르는 이유: 레거시는 법인별 DB 였고 매출은 그 DB 의 도서를 팔았다.
--      연구소 상품을 리브 장부 거래처로 판 건(실측 16건)은 **연구소 매출**로 본다.
UPDATE sales SET corp = 'DSLAB'     WHERE sales_no LIKE 'DL-%';
UPDATE sales SET corp = 'DSTXTBOOK' WHERE sales_no LIKE 'DT-%';
UPDATE sales s JOIN products p ON p.id = s.product_id
   SET s.corp = p.corp
 WHERE s.corp IS NULL AND p.corp IS NOT NULL;

-- 4) 수금 — 이관분은 전표번호 접두어, 신규분은 그 거래처를 따라간다.
UPDATE collection SET corp = 'DSLAB'     WHERE collection_no LIKE 'DL-C-%';
UPDATE collection SET corp = 'DSTXTBOOK' WHERE collection_no LIKE 'DT-C-%';
UPDATE collection c JOIN partners pt ON pt.id = c.partner_id
   SET c.corp = pt.corp
 WHERE c.corp IS NULL AND pt.corp IS NOT NULL;

-- 5) 재고이벤트 — 그 상품을 따라간다.
--    ‼️자재 이벤트(material_id 가 있는 행)는 **NULL 로 남긴다** — 자재에는 법인 축이 없다.
--      근거 없이 연구소로 채우면 자재 원장이 한쪽 법인 것으로 보인다.
UPDATE inventory_txn t JOIN products p ON p.id = t.product_id
   SET t.corp = p.corp
 WHERE t.product_id IS NOT NULL AND p.corp IS NOT NULL;

-- 6) 발송 — 그 거래처를 따라간다.
UPDATE shipment sh JOIN partners pt ON pt.id = sh.partner_id
   SET sh.corp = pt.corp
 WHERE pt.corp IS NOT NULL;

-- 7) 이월 — 그 거래처를 따라간다.
UPDATE receivable_carryforward rc JOIN partners pt ON pt.id = rc.partner_id
   SET rc.corp = pt.corp
 WHERE pt.corp IS NOT NULL;
